import express from 'express';
const app = express();
app.get('/', () => {
  throw Object.assign(new Error('x'), { status: 404 });
});
app.use((err, req, res, next) => res.sendStatus(err.status ?? 500));
const s = app.listen(3000);
console.log((await fetch('http://localhost:3000/')).status);
s.close();
